BEGIN TRANSACTION;
CREATE TABLE affect_state (
      run INTEGER, 
      cons_id TEXT REFERENCES consciousnesses(cons_id), 
      target TEXT,
      trust INTEGER, 
      intimacy INTEGER, 
      alert INTEGER,
      fsm_state TEXT CHECK(fsm_state IN ('open','probing','guarded','detached')),
      PRIMARY KEY (run, cons_id, target)
    );
CREATE TABLE anchor_channel (
  run INTEGER PRIMARY KEY,
  snr REAL DEFAULT 1.0,
  lt_filter REAL DEFAULT 0.0,
  diversity TEXT DEFAULT '[]'
);
CREATE TABLE archetypes (
      arch_id      TEXT PRIMARY KEY,
      display_name TEXT NOT NULL
    );
CREATE TABLE bleed_config(
  cons_id TEXT PRIMARY KEY, base_bleed REAL DEFAULT 0,
  growth_per_delta REAL DEFAULT 0, restart_immunity REAL DEFAULT 0);
CREATE TABLE bodies (
      body_id      TEXT PRIMARY KEY,
      origin_wl    TEXT NOT NULL REFERENCES worldlines(wl_id),
      arch_id      TEXT REFERENCES archetypes(arch_id),
      body_type    TEXT NOT NULL CHECK(body_type IN ('human','artificial','machine_hybrid')),
      rtw_code     TEXT,
      note         TEXT
    );
CREATE TABLE body_state(
  run INTEGER, body_id TEXT, asof_event INTEGER, wl_id TEXT,
  location_id TEXT, hp TEXT, holding TEXT, PRIMARY KEY(run,body_id));
CREATE TABLE body_transfers (
      xfer_id      INTEGER PRIMARY KEY AUTOINCREMENT,
      body_id      TEXT NOT NULL REFERENCES bodies(body_id),
      from_wl      TEXT REFERENCES worldlines(wl_id),
      to_wl        TEXT NOT NULL REFERENCES worldlines(wl_id),
      via          TEXT,
      at_event     INTEGER,
      canon_src    TEXT
    );
CREATE TABLE canon_locks (
      lock_id      TEXT PRIMARY KEY,
      node_id      TEXT,
      ch_ref       INTEGER,
      locked_text  TEXT NOT NULL,
      context      TEXT,
      speaker_cons TEXT REFERENCES consciousnesses(cons_id)
    );
CREATE TABLE causal_constants (
  const_id   TEXT PRIMARY KEY,
  prop_id    TEXT REFERENCES propositions(prop_id),
  lock_type  TEXT CHECK(lock_type IN ('self_reference','anchor_dependency')),
  dependency_chain TEXT NOT NULL,   -- JSON: 自指链事件/命题序列（终幕渲染）
  canon_src  TEXT
);
CREATE TABLE coherence_matrix (
  cons_id TEXT PRIMARY KEY,
  coupling REAL DEFAULT 0.0,
  note TEXT
);
CREATE TABLE consciousnesses (
      cons_id      TEXT PRIMARY KEY,
      native_wl    TEXT NOT NULL REFERENCES worldlines(wl_id),
      arch_id      TEXT NOT NULL REFERENCES archetypes(arch_id),
      jump_capable INTEGER DEFAULT 0,
      note         TEXT
    );
CREATE TABLE delta_ledger(
  delta_id INTEGER PRIMARY KEY, run INTEGER NOT NULL, node_id TEXT,
  description TEXT, converged INTEGER DEFAULT 0, emo_tag TEXT, src_event INTEGER);
CREATE TABLE delta_sediment (
  sid INTEGER PRIMARY KEY,
  node_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  payload TEXT NOT NULL,
  cons_id TEXT,
  weight REAL NOT NULL,
  src_run INTEGER NOT NULL,
  src_delta TEXT NOT NULL,
  revoked INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  CHECK (kind IN ('precedent', 'scar', 'unlock', 'witness')),
  CHECK (src_run >= 1),
  CHECK (revoked IN (0, 1))
);
CREATE TABLE events(
  event_id INTEGER PRIMARY KEY, run INTEGER NOT NULL, wl_id TEXT,
  t_game INTEGER, ch_anchor INTEGER, location_id TEXT,
  etype TEXT, payload TEXT, parent_event INTEGER);
CREATE TABLE fronting_canon(
  fc_id INTEGER PRIMARY KEY AUTOINCREMENT,
  body_id TEXT, scene TEXT, ch_ref TEXT,
  fronting_cons TEXT, back_state TEXT, canon_src TEXT);
CREATE TABLE fronting_state(
  run INTEGER, body_id TEXT, fronting_cons TEXT, asof_event INTEGER,
  PRIMARY KEY(run,body_id));
CREATE TABLE identity_beliefs (
      run INTEGER,
      observer_cons TEXT REFERENCES consciousnesses(cons_id),
      body_id       TEXT REFERENCES bodies(body_id),
      believed_cons TEXT REFERENCES consciousnesses(cons_id),
      doubt         REAL DEFAULT 0.0,
      asof_event    INTEGER,
      PRIMARY KEY (run, observer_cons, body_id)
    );
CREATE TABLE item_custody(
  run INTEGER, item_id TEXT, holder_body TEXT, from_event INTEGER, to_event INTEGER);
CREATE TABLE items(item_id TEXT PRIMARY KEY, display_name TEXT, note TEXT);
CREATE TABLE knowledge_runtime(
  run INTEGER, cons_id TEXT, prop_id TEXT, acquired_event INTEGER,
  confidence REAL DEFAULT 1.0, PRIMARY KEY(run,cons_id,prop_id));
CREATE TABLE knowledge_schedule (
      cons_id      TEXT REFERENCES consciousnesses(cons_id),
      prop_id      TEXT REFERENCES propositions(prop_id),
      learn_ch     INTEGER NOT NULL,
      source_desc  TEXT,
      PRIMARY KEY (cons_id, prop_id)
    );
CREATE TABLE node_contracts(node_id TEXT PRIMARY KEY, part INTEGER, contract TEXT);
CREATE TABLE occupancy (
      occ_id       INTEGER PRIMARY KEY AUTOINCREMENT,
      body_id      TEXT NOT NULL REFERENCES bodies(body_id),
      cons_id      TEXT NOT NULL REFERENCES consciousnesses(cons_id),
      from_event   INTEGER,
      to_event     INTEGER,
      occ_mode     TEXT CHECK(occ_mode IN ('native','jump_in','restored','installed','co_resident')),
      canon_src    TEXT
    );
CREATE TABLE propositions (
      prop_id      TEXT PRIMARY KEY,
      statement    TEXT NOT NULL,
      spoiler_tier INTEGER NOT NULL,
      canon_src    TEXT
    );
CREATE TABLE run_bonds (
      run INTEGER,
      character_id TEXT,
      action_flag TEXT,
      timestamp TEXT,
      PRIMARY KEY (run, character_id, action_flag)
    );
CREATE TABLE run_meta (
  run INTEGER PRIMARY KEY,
  parent_run INTEGER NOT NULL,
  kind TEXT NOT NULL,
  fork_event TEXT,
  inherit_level INTEGER NOT NULL,
  player_line TEXT NOT NULL DEFAULT 'a_qi',
  opening_id TEXT,
  player_profile_hash TEXT,
  opened_at TEXT,
  closed_at TEXT,
  final_delta_summary TEXT,
  CHECK (run >= 1),
  CHECK (kind IN ('fresh', 'beta', 'fork')),
  CHECK (inherit_level IN (0, 1, 2))
);
CREATE TABLE slow_memory (
      mem_id INTEGER PRIMARY KEY AUTOINCREMENT,
      run INTEGER, 
      cons_id TEXT REFERENCES consciousnesses(cons_id),
      text TEXT NOT NULL, 
      anchor TEXT,
      salience REAL, 
      emo_tag TEXT,
      src_event INTEGER, 
      available_ch INTEGER,
      projection_text TEXT,
      reveal_ch INTEGER,
      embedding BLOB
    );
CREATE TABLE snapshots(
  snap_id INTEGER PRIMARY KEY, run INTEGER, node_id TEXT, created_at INTEGER, blob BLOB);
CREATE TABLE source_manifest(
  seq INTEGER PRIMARY KEY, filename TEXT NOT NULL,
  ch_from INTEGER, ch_to INTEGER, note TEXT);
CREATE TABLE worldlines (
      wl_id        TEXT PRIMARY KEY,
      parent_wl    TEXT REFERENCES worldlines(wl_id),
      desync_ms    INTEGER DEFAULT 0,
      note         TEXT
    );
CREATE TABLE xline_messages (
  msg_id INTEGER PRIMARY KEY, run INTEGER,
  from_wl TEXT, to_wl TEXT, channel TEXT,           -- LT_ANCHOR / PHONE / DATAPACK
  t_send INTEGER NOT NULL, t_observed INTEGER NOT NULL,  -- 引擎算，禁手填
  payload TEXT
);
CREATE INDEX idx_canon_locks_speaker_cons ON canon_locks(speaker_cons);
CREATE INDEX idx_slow_memory_cons_id ON slow_memory(cons_id);
CREATE INDEX idx_events_ch_anchor ON events(ch_anchor);
CREATE INDEX idx_delta_sediment_node ON delta_sediment(node_id);
CREATE INDEX idx_delta_sediment_src_run ON delta_sediment(src_run);
CREATE INDEX idx_delta_sediment_kind ON delta_sediment(kind);
CREATE INDEX idx_run_meta_parent ON run_meta(parent_run);
DELETE FROM "sqlite_sequence";
COMMIT;
