INSERT INTO "canon_locks" VALUES('L.zhangchen.wmain.0178',NULL,32,'我，不清楚……','“我，不清楚……”周泽从昨天早上受到张尘的“恐吓”之后就开始冷汗不断，现在也一样，','C.zhangchen.WMAIN');
