INSERT INTO "canon_locks" VALUES('L.zhangchen.wmain.0180',NULL,33,'逗谁呢老大，这里可是男厕。','“逗谁呢老大，这里可是男厕。”张尘没有停下来的意思。','C.zhangchen.WMAIN');
INSERT INTO "canon_locks" VALUES('L.zhangchen.wmain.0181',NULL,33,'你个……流氓！','“你个……流氓！”魏初一掌拍在张尘后脑勺，然后怒气冲冲地离开男厕，平静下来才发现','C.zhangchen.WMAIN');
