INSERT INTO "canon_locks" VALUES('L.zhangchen.wmain.0183',NULL,33,'多管闲事的下场就是自讨苦吃。','印？“多管闲事的下场就是自讨苦吃。”张尘拍打着自己的脸，心理暗示着自己继续保持清','C.zhangchen.WMAIN');
