INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1089',NULL,90,'还有，你都可以随便打我骂我的，所以也可以随意指挥我，','“还有，你都可以随便打我骂我的，所以也可以随意指挥我，”修哉在想，以真纪的性格而','C.xiuzai.WMAIN');
INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1090',NULL,90,'我不嫌麻烦，','言没可能不担心那座城的亲友，可她又绝口不提，修哉不喜欢和她拐弯抹角，“我不嫌麻烦，','C.xiuzai.WMAIN');
INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1091',NULL,90,'姐。','“姐。”一声天才，修哉感觉和她相隔无法逾越的次元。','C.xiuzai.WMAIN');
