INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1093',NULL,90,'嗯，','“嗯，”修哉不会理解真纪对自己说这些的用意，但还是很开心地笑着，“没关系啊，不明白','C.xiuzai.WMAIN');
