INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1098',NULL,91,'你们居然不是黑社会。','轻声笑着听修哉冷不丁问一句：“你们居然不是黑社会。”','C.xiuzai.WMAIN');
