INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1107',NULL,91,'毁了东京塔。','“毁了东京塔。”平静得说着令人背脊寒凉的话，修哉僵硬着转过头：“你是，开玩笑的吧。”','C.xiuzai.WMAIN');
