INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1110',NULL,91,'六本木 Hills。','“六本木 Hills。”修哉曾经还很喜欢那个地方，可是比起那些承载自己记忆的场所，宁愿毁','C.xiuzai.WMAIN');
