INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1117',NULL,91,'毕竟 DS，那可是黑社会啊，','“毕竟 DS，那可是黑社会啊，”卡卡西揽过修哉肩膀，“怎么样，呆会天黑要不要一起去红','C.xiuzai.WMAIN');
