INSERT INTO "canon_locks" VALUES('L.xiuzai.wmain.1130',NULL,92,'额嗯，嗯呜，','“额嗯，嗯呜，”修哉掏着口袋慌乱抓出钱包，“问这干什么。”','C.xiuzai.WMAIN');
