INSERT INTO "canon_locks" VALUES('L.kakashi.1345',NULL,77,'嗯。','“嗯。”卡卡西连点头的心情都没有，脑海中不断回放“他们”离开自己时的场景。父亲死','C.kakashi.WMAIN');
