INSERT INTO "canon_locks" VALUES('L.kakashi.1364',NULL,77,'讽刺就不愉快了，','“讽刺就不愉快了，”卡卡西无奈着，“其实当山本先生出现在医院中的时候，我就猜到些不','C.kakashi.WMAIN');
