INSERT INTO "canon_locks" VALUES('L.kakashi.1368',NULL,77,'坂本晴明，旗木卡卡西，','“坂本晴明，旗木卡卡西，”山本托着下巴，“因为你和他们不一样，作为这样一个身份，你','C.kakashi.WMAIN');
