INSERT INTO "canon_locks" VALUES('L.kakashi.1370',NULL,77,'简单地说为了蒙蔽佐助和小樱，中岛编了一套胡闹的说辞，说','卡卡西过多纠结这些事情，“简单地说为了蒙蔽佐助和小樱，中岛编了一套胡闹的说辞，说','C.kakashi.WMAIN');
INSERT INTO "canon_locks" VALUES('L.kakashi.1371',NULL,77,'抱歉，','“抱歉，”卡卡西再次打断他，同时打开车门，“抱歉我现在并不想听，今晚……就罢了。”','C.kakashi.WMAIN');
