INSERT INTO "events" VALUES(401,0,'W-MAIN',0,4,'修哉公寓客厅','action','{"event_uid": "E004-01", "witnesses": ["C.kakashi.WMAIN", "C.xiuzai.WMAIN", "C.akito.WMAIN"], "action": "秋人回国误会两人“出柜”，卡卡西揭下眼罩当场开启写轮眼万花筒并用神威传送走咖啡杯。", "motive": "降维自证与省去低效解释", "causality": "→E004-02", "knowledge_change": "C.akito.WMAIN ← 得知室友晴明拥有写轮眼万花筒超能力", "items": "", "intervention_flag": "", "canon_src": "n1-69:Ch.4"}',302);
