INSERT INTO "events" VALUES(10904,0,'W-MAIN',0,109,'某公寓','action','{"event_uid": "E109-04", "witnesses": ["C.yamato.WMAIN", "C.zhangchen.WMAIN"], "action": "大和天藏把一封信给小张尘，嘱咐她去找信上地址的人，自己独自离开。", "motive": "大和有自己的任务要走", "causality": "小张尘带信去寻找魏初", "knowledge_change": "小张尘接到跑腿任务", "items": "信件", "intervention_flag": "大和离别", "canon_src": "Chapter109"}',NULL);
INSERT INTO "events" VALUES(10905,0,'W-MAIN',0,109,'魏初公寓','action','{"event_uid": "E109-05", "witnesses": ["C.weichu.WMAIN", "C.banbo.WMAIN", "C.yuxuan.WMAIN", "C.liuyuntian.WMAIN", "C.zhangchen.WMAIN"], "action": "小张尘带着信来到魏初公寓，魏初斑驳雨璇正在照顾昏睡的刘云天。", "motive": "投递信件", "causality": "魏初等人收留小张尘", "knowledge_change": "魏初等人得知大和的信件内容", "items": "信件", "intervention_flag": "魏初接收小张尘", "canon_src": "Chapter109"}',NULL);
INSERT INTO "events" VALUES(11001,0,'W-MAIN',0,110,'过去线回忆','action','{"event_uid": "E110-01", "witnesses": ["C.ryuya.WMAIN", "C.zhangchen.WMAIN"], "action": "回忆中反社会的龙也讲述自己有精神分裂，利用身体杀死了张尘的女友。另一个龙也与张尘结为挚友。", "motive": "反社会龙也出于杀人欲望", "causality": "张尘因此痛恨自己，龙也内部分裂加剧", "knowledge_change": "读者了解龙也双重人格真相", "items": "枪支", "intervention_flag": "反社会龙也犯案", "canon_src": "Chapter110"}',NULL);
INSERT INTO "events" VALUES(11002,0,'W-MAIN',0,110,'废弃城市房顶','action','{"event_uid": "E110-02", "witnesses": ["C.xiuzai.WMAIN", "C.kakashi.WMAIN", "C.dust.W1"], "action": "转移后三人来到被毁灭的城市，张尘解答DTR武器原理是脑电波共振，并要带卡卡西找人。", "motive": "解释原理并寻找目标", "causality": "三人结伴在废墟中前行", "knowledge_change": "修哉卡卡西得知DTR原理", "items": "无", "intervention_flag": "DTR原理揭示", "canon_src": "Chapter110"}',NULL);
INSERT INTO "events" VALUES(11101,0,'W-MAIN',0,111,'回忆线','action','{"event_uid": "E111-01", "witnesses": ["C.banbo.WMAIN", "C.yuxuan.WMAIN", "C.zhangchen.WMAIN"], "action": "斑驳雨璇回忆过去张尘广播预言城市即将毁灭，未受政府理睬，最终张尘死去。", "motive": "回忆张尘的牺牲", "causality": "斑驳雨璇感到无力与遗憾", "knowledge_change": "无", "items": "初音专辑(回忆中)", "intervention_flag": "张尘灭城警告事件", "canon_src": "Chapter111"}',NULL);
INSERT INTO "events" VALUES(11102,0,'W-MAIN',0,111,'废弃城市街道','action','{"event_uid": "E111-02", "witnesses": ["C.xiuzai.WMAIN", "C.kakashi.WMAIN", "C.dust.W1"], "action": "张尘坦白自己是来自另一个平行世界的张尘，那个世界里修哉是物理学家，张尘是意识跳转实验志愿者。", "motive": "张尘讲述来历", "causality": "修哉与卡卡西理解平行世界", "knowledge_change": "得知意识跳转计划(RTW)", "items": "无", "intervention_flag": "张尘讲述身世", "canon_src": "Chapter111"}',NULL);
INSERT INTO "events" VALUES(11201,0,'W-MAIN',0,112,'另一个世界的过去','action','{"event_uid": "E112-01", "witnesses": ["C.dust.W1", "C.xiuzai.WMAIN", "C.ryuya.WMAIN"], "action": "跳转前，张尘与龙也和修哉告别。修哉发誓会接他回来。张尘进入传送机器。", "motive": "寻找人类存在的意义", "causality": "张尘意识跳转成功，离开原世界", "knowledge_change": "无", "items": "机器设备", "intervention_flag": "意识跳转前夕", "canon_src": "Chapter112"}',NULL);
INSERT INTO "events" VALUES(11202,0,'W-MAIN',0,112,'异世界第二跳','action','{"event_uid": "E112-02", "witnesses": ["C.dust.W1", "~维多·邦纳赛拉", "C.ryuya.W1"], "action": "张尘在异世界救护站醒来，被维多背着。看到高科技飞船。异世界的龙也出现。", "motive": "意识跳转落地", "causality": "发现异世界科技极度发达", "knowledge_change": "张尘了解异世界状况", "items": "担架飞船", "intervention_flag": "张尘到达第二世界", "canon_src": "Chapter112"}',NULL);
INSERT INTO "events" VALUES(11203,0,'W-MAIN',0,112,'异世界世界政府','action','{"event_uid": "E112-03", "witnesses": ["C.dust.W1", "C.ryuya.W1"], "action": "龙也带张尘去RTW控制室，告知该世界过于完美失去意义即将毁灭，送张尘进入RTW-LT做最后跳转阻止悲剧。", "motive": "为了挽救人类未来", "causality": "张尘被迫再次跳转", "knowledge_change": "得知完美世界的毁灭危机", "items": "传送装置", "intervention_flag": "张尘再次跳转", "canon_src": "Chapter112"}',NULL);
INSERT INTO "events" VALUES(11301,0,'W-MAIN',0,113,'某个世界回忆','action','{"event_uid": "E113-01", "witnesses": ["C.dust.W1", "C.akito.WMAIN", "C.nakajima.WMAIN"], "action": "张尘跳转后遇到秋人、中岛，发现这个世界修哉已死，但被米娅提取大脑，与另一身体缝合为人造人。", "motive": "得知修哉变身人造人真相", "causality": "发现时空机器的真面目", "knowledge_change": "了解修哉的大脑被保存", "items": "医疗仪器", "intervention_flag": "发现修哉的残存体", "canon_src": "Chapter113"}',NULL);
INSERT INTO "events" VALUES(11302,0,'W-MAIN',0,113,'废弃城市','action','{"event_uid": "E113-02", "witnesses": ["C.xiuzai.WMAIN", "C.kakashi.WMAIN", "C.dust.W1", "~米娅·海森堡", "~黑发卡卡西"], "action": "张尘带修哉等人找到一身黑的米娅。张尘叫出黑发卡卡西(时空机器)，命其带自己离开。", "motive": "张尘结束本次引导", "causality": "未来张尘消失，真正的当前时空张尘重新出现", "knowledge_change": "三人得见时空机器真面目", "items": "无", "intervention_flag": "张尘召唤黑发卡卡西", "canon_src": "Chapter113"}',NULL);
INSERT INTO "events" VALUES(11303,0,'W-MAIN',0,113,'废弃城市','action','{"event_uid": "E113-03", "witnesses": ["C.xiuzai.WMAIN", "C.kakashi.WMAIN", "C.zhangchen.WMAIN"], "action": "真正的张尘重现，跪在地上。", "motive": "张尘恢复原身意识", "causality": "接续当前时空的故事", "knowledge_change": "无", "items": "无", "intervention_flag": "真正张尘回归", "canon_src": "Chapter113"}',NULL);
INSERT INTO "events" VALUES(11401,0,'W-MAIN',0,114,'魏初公寓','action','{"event_uid": "E114-01", "witnesses": ["C.banbo.WMAIN", "C.yuxuan.WMAIN"], "action": "魏初开车出门。雨璇斑驳在家翻看《百年孤独》，发现内容与记忆不同，确认身处平行宇宙。", "motive": "察觉世界变化", "causality": "接受平行世界现实", "knowledge_change": "确认平行宇宙假说", "items": "书籍《百年孤独》", "intervention_flag": "阅读书籍发现异常", "canon_src": "Chapter114"}',NULL);
INSERT INTO "events" VALUES(11402,0,'W-MAIN',0,114,'开发区岔路','action','{"event_uid": "E114-02", "witnesses": ["C.weichu.WMAIN", "C.zhangchen.WMAIN", "C.xiuzai.WMAIN", "C.kakashi.WMAIN", "~米娅·海森堡"], "action": "魏初开车赶到，斥责变年轻的张尘，将LT钥匙(钢笔)还给他。张尘崩溃痛哭，修哉与卡卡西上前安抚。", "motive": "魏初交还钥匙，张尘发泄情绪", "causality": "众人决定不再孤军奋战，拟定新计划", "knowledge_change": "无", "items": "LT标志的钢笔", "intervention_flag": "张尘崩溃与众人和解", "canon_src": "Chapter114"}',NULL);
INSERT INTO "events" VALUES(11501,0,'W-MAIN',0,115,'异世界实验室','action','{"event_uid": "E115-01", "witnesses": ["C.dust.W1", "~坂本玲于奈"], "action": "张尘与人造人玲于奈交谈，得知该时空人造人剥夺情感技术。玲于奈指出黑发卡卡西能控制时空跃迁，但由修哉大脑主导。", "motive": "探讨人造人与情感", "causality": "张尘理解时空机器运作", "knowledge_change": "得知时空机器控制权", "items": "试管, 机器", "intervention_flag": "张尘与玲于奈对话", "canon_src": "Chapter115"}',NULL);
INSERT INTO "events" VALUES(11502,0,'W-MAIN',0,115,'异世界实验室','action','{"event_uid": "E115-02", "witnesses": ["C.dust.W1", "~索恩博士", "C.ryuya.WMAIN"], "action": "张尘看完失去意识的龙也，与索恩博士告别，带着那个人造人(黑发卡卡西)启程跳转。", "motive": "踏上新的时空旅途", "causality": "开始漫长的时空穿越", "knowledge_change": "无", "items": "时空机器", "intervention_flag": "张尘带机器离开", "canon_src": "Chapter115"}',NULL);
INSERT INTO "events" VALUES(11503,0,'W-MAIN',0,115,'时空旅途中','action','{"event_uid": "E115-03", "witnesses": ["C.dust.W1", "~黑发卡卡西(人造人晴明)"], "action": "某次张尘喝醉割腕自残，被黑发卡卡西制止并包扎。黑发卡卡西自称要寻找“心”。", "motive": "张尘绝望放纵，机器展现关怀", "causality": "张尘开始教导机器学习格斗和常人喜好", "knowledge_change": "机器开始萌生情感概念", "items": "碎玻璃瓶", "intervention_flag": "割腕自残与包扎", "canon_src": "Chapter115"}',NULL);
INSERT INTO "events" VALUES(11601,0,'W-MAIN',0,116,'日本据点','action','{"event_uid": "E116-01", "witnesses": ["C.leonard.WMAIN", "C.yamamoto_che.WMAIN"], "action": "莱纳德和山本分析密码信，破解出BADA暗号，指出三战将波及亚洲。", "motive": "解析情报", "causality": "为DS下一步行动指明方向", "knowledge_change": "得知战争波及亚洲", "items": "密码信, 白板", "intervention_flag": "莱纳德解密信件", "canon_src": "Chapter116"}',NULL);
INSERT INTO "events" VALUES(11602,0,'W-MAIN',0,116,'据点酒吧','action','{"event_uid": "E116-02", "witnesses": ["~维多·邦纳赛拉", "C.wuxiaxian.WMAIN"], "action": "吴夏弦告知维多张尘等人在中国，邀请他一起前往。维多同意。", "motive": "汇集同伴", "causality": "决定前往中国汇合", "knowledge_change": "得知张尘下落", "items": "酒杯", "intervention_flag": "吴夏弦说服维多", "canon_src": "Chapter116"}',NULL);
INSERT INTO "events" VALUES(11603,0,'W-MAIN',0,116,'街道','action','{"event_uid": "E116-03", "witnesses": ["C.itachi.WMAIN", "C.sasuke.WMAIN"], "action": "鼬和佐助散步，带着卡布。两人聊天并决定继续参战，要去中国找张尘等人。", "motive": "兄弟交心与决策", "causality": "坚定了参战立场", "knowledge_change": "无", "items": "机器人卡布", "intervention_flag": "佐助鼬交谈", "canon_src": "Chapter116"}',NULL);
INSERT INTO "events" VALUES(11604,0,'W-MAIN',0,116,'日本据点会议室','action','{"event_uid": "E116-04", "witnesses": ["C.leonard.WMAIN", "C.yamamoto_che.WMAIN", "C.guojiazheng.WMAIN", "C.wuxiaxian.WMAIN", "C.nakajima.WMAIN"], "action": "众人开会决定飞往中国。吴夏弦提供波音747偷渡，中岛提出用佐助和鼬的瞳术护航。", "motive": "制定前往中国的计划", "causality": "准备出发前往战场", "knowledge_change": "无", "items": "地图, 波音747(提及)", "intervention_flag": "会议决定偷渡", "canon_src": "Chapter116"}',NULL);
INSERT INTO "events" VALUES(11605,0,'W-MAIN',0,116,'阳台','action','{"event_uid": "E116-05", "witnesses": ["C.naruto.WMAIN", "C.sakura.WMAIN", "~波风水门"], "action": "鸣人与樱探讨战后生活，鸣人想送快递，樱想做护士，水门在暗处欣慰观察。", "motive": "对未来的畅想", "causality": "缓和战前紧张气氛", "knowledge_change": "无", "items": "无", "intervention_flag": "鸣人樱夜谈", "canon_src": "Chapter116"}',NULL);
INSERT INTO "events" VALUES(11606,0,'W-MAIN',0,116,'某窗台/阳台','action','{"event_uid": "E116-06", "witnesses": ["C.maki.WMAIN", "C.liuxu.WMAIN"], "action": "真纪留下给云天的告别录音，阻止柳絮跟随，决定独自前往中国战场寻找修哉。", "motive": "奔赴战场保护家人", "causality": "柳絮留在日本，真纪奔赴前线", "knowledge_change": "无", "items": "手机", "intervention_flag": "真纪告别", "canon_src": "Chapter116"}',NULL);
INSERT INTO "events" VALUES(11701,0,'W-MAIN',0,117,'过去回忆','action','{"event_uid": "E117-01", "witnesses": ["C.akito.WMAIN", "C.xiuzai.WMAIN", "C.ryuya.WMAIN"], "action": "秋人回忆被修哉赏识成为挚友，后来修哉失去情感当面割腕，秋人夺刀受伤。吴叔劝其离开。", "motive": "回忆两人羁绊与决裂", "causality": "秋人手部受伤，接受吴叔建议离开", "knowledge_change": "无", "items": "存折, 刀", "intervention_flag": "秋人回忆往事", "canon_src": "Chapter117"}',NULL);
INSERT INTO "events" VALUES(11702,0,'W-MAIN',0,117,'开发区车内','action','{"event_uid": "E117-02", "witnesses": ["C.zhangchen.WMAIN", "C.xiuzai.WMAIN", "C.kakashi.WMAIN", "C.weichu.WMAIN", "~米娅·海森堡"], "action": "张尘让卡卡西用钢笔在空中写下10位圆周率，钢笔变形为LT会议室的唯一钥匙(图腾容器)。", "motive": "演示钥匙启动", "causality": "众人得知LT钥匙的真面目", "knowledge_change": "得知如何进入LT会议室", "items": "LT钢笔/钥匙", "intervention_flag": "钥匙变形启动", "canon_src": "Chapter117"}',NULL);
INSERT INTO "events" VALUES(11703,0,'W-MAIN',0,117,'世界政府监控室','action','{"event_uid": "E117-03", "witnesses": ["C.akito.WMAIN", "~山崎聪", "~白大褂"], "action": "几名白大褂进入房间，强行给秋人的脊髓注射不明液体。秋人陷入呆滞，透过监视器向山崎聪求救，山崎聪大为震惊。", "motive": "强行进行人体实验", "causality": "秋人沦为实验品，山崎聪心理动摇", "knowledge_change": "山崎聪目睹残酷实验", "items": "注射器", "intervention_flag": "强行注射实验", "canon_src": "Chapter117"}',NULL);
INSERT INTO "events" VALUES(11801,0,'W-MAIN',0,118,'飞机客舱','action','{"event_uid": "E118-01", "witnesses": ["C.maki.WMAIN", "C.zhangchen.WMAIN", "C.kakashi.WMAIN", "C.xiuzai.WMAIN", "~众人"], "action": "真纪发表演讲，安抚众人，表达对自己信仰正义的坚持。", "motive": "鼓舞士气", "causality": "众人感到被肯定，坚定信念", "knowledge_change": "了解真纪的立场", "items": "无", "intervention_flag": "真纪演讲", "canon_src": "Chapter118"}',NULL);
INSERT INTO "events" VALUES(11802,0,'W-MAIN',0,118,'飞机驾驶舱','action','{"event_uid": "E118-02", "witnesses": ["~副机长"], "action": "飞机遭导弹锁定，老机长切断自动导航手动驾驶避开一击。", "motive": "逃避导弹攻击", "causality": "飞机暂时脱险", "knowledge_change": "无", "items": "飞机", "intervention_flag": "飞机遭遇导弹", "canon_src": "Chapter118"}',NULL);
INSERT INTO "events" VALUES(11803,0,'W-MAIN',0,118,'高空/飞机残骸中','action','{"event_uid": "E118-03", "witnesses": ["C.kakashi.WMAIN", "C.naruto.WMAIN", "C.sasuke.WMAIN", "C.itachi.WMAIN"], "action": "卡卡西跳出飞机，使用近距离神威转移导弹到敌机群中引爆，力竭坠落。鸣人爆开仙人模式跳出飞机营救。", "motive": "消除敌机威胁，保护飞机", "causality": "敌机全灭，卡卡西与鸣人坠海", "knowledge_change": "无", "items": "导弹", "intervention_flag": "卡卡西转移导弹", "canon_src": "Chapter118"}',NULL);
INSERT INTO "events" VALUES(11901,0,'W-MAIN',0,119,'战舰','action','{"event_uid": "E119-01", "witnesses": ["C.liuxu.WMAIN", "C.wuxiaxian.WMAIN"], "action": "柳絮换上军装，向吴夏弦表明只想见晴明一面。吴夏弦决定静观其变。", "motive": "柳絮找寻自我，吴夏弦观察局势", "causality": "柳絮明确心意，战舰等待时机", "knowledge_change": "无", "items": "军装", "intervention_flag": "柳絮的心意", "canon_src": "Chapter119"}',NULL);
INSERT INTO "events" VALUES(11902,0,'W-MAIN',0,119,'飞机客舱','action','{"event_uid": "E119-02", "witnesses": ["C.xiuzai.WMAIN", "~波风水门", "C.yamamoto_che.WMAIN"], "action": "修哉启动木马程序恢复飞机GPS，众人寻找迫降地点。", "motive": "寻找迫降方案", "causality": "飞机获得降落希望", "knowledge_change": "无", "items": "木马程序", "intervention_flag": "恢复GPS", "canon_src": "Chapter119"}',NULL);
INSERT INTO "events" VALUES(12001,0,'W-MAIN',0,120,'过去回忆','action','{"event_uid": "E120-01", "witnesses": ["C.zhangchen.WMAIN", "C.banbo.WMAIN", "C.yuxuan.WMAIN", "C.kakashi.WMAIN"], "action": "张尘与斑驳、雨璇道别，安抚斑驳的情绪，随后带卡卡西离开。", "motive": "告别与宽慰", "causality": "斑驳雨璇解开心结", "knowledge_change": "无", "items": "无", "intervention_flag": "斑驳雨璇告别", "canon_src": "Chapter120"}',NULL);
INSERT INTO "events" VALUES(12101,0,'W-MAIN',0,121,'异世界记忆','action','{"event_uid": "E121-01", "witnesses": ["C.ryuya.WMAIN", "C.zhangchen.WMAIN", "~折原正义", "C.xiuzai.WMAIN"], "action": "龙也进行意识跳转，到达第30541号世界，试图阻碍张尘成长但失败。回忆正义种西瓜的道理。", "motive": "试图改变张尘命运", "causality": "发现张尘命运难以改变", "knowledge_change": "得知张尘在其他世界的成就", "items": "西瓜", "intervention_flag": "龙也干涉异世界", "canon_src": "Chapter121"}',NULL);
INSERT INTO "events" VALUES(12201,0,'W-MAIN',0,122,'异世界记忆','action','{"event_uid": "E122-01", "witnesses": ["C.ryuya.WMAIN", "C.zhangchen.WMAIN"], "action": "反社会人格龙也夺回身体控制权，在枪战中为保护张尘挡子弹死亡。", "motive": "保护张尘", "causality": "异世界龙也死亡", "knowledge_change": "无", "items": "枪支", "intervention_flag": "龙也保护张尘", "canon_src": "Chapter122"}',NULL);
INSERT INTO "events" VALUES(12202,0,'W-MAIN',0,122,'现实医院','action','{"event_uid": "E122-02", "witnesses": ["C.ryuya.WMAIN", "C.xiuzai.WMAIN", "C.zhangchen.WMAIN"], "action": "龙也回到现实，面对脑死亡的张尘，宣告张尘于2051年死亡。龙也修哉决定寻找张尘。", "motive": "面对张尘死亡", "causality": "坚定了寻找张尘的决心", "knowledge_change": "确认张尘死亡时间", "items": "无", "intervention_flag": "张尘宣告死亡", "canon_src": "Chapter122"}',NULL);
INSERT INTO "events" VALUES(12301,0,'W-MAIN',0,123,'废弃机场','action','{"event_uid": "E123-01", "witnesses": ["C.zhangchen.WMAIN", "C.leonard.WMAIN", "C.guojiazheng.WMAIN", "~维多·邦纳赛拉"], "action": "飞机迫降后，莱纳德用枪指着张尘，质问世界政府、LT和DS的真相。张尘作出回答。", "motive": "质问真相", "causality": "揭开组织真实面目", "knowledge_change": "莱纳德得知政府、LT、DS关系", "items": "枪支", "intervention_flag": "莱纳德质问张尘", "canon_src": "Chapter123"}',NULL);
INSERT INTO "events" VALUES(12302,0,'W-MAIN',0,123,'海滩机舱','action','{"event_uid": "E123-02", "witnesses": ["C.kakashi.WMAIN", "C.zhangchen.WMAIN"], "action": "卡卡西向张尘保证自己不会死，张尘用恐龙化石质问人类存在意义，怀疑人类是高等生物玩具。", "motive": "哲学探讨与悲观猜想", "causality": "卡卡西被张尘言语震慑", "knowledge_change": "得知张尘对人类历史的猜想", "items": "化石(提及)", "intervention_flag": "张尘的恐龙质问", "canon_src": "Chapter123"}',NULL);
INSERT INTO "events" VALUES(12303,0,'W-MAIN',0,123,'渤海海域战舰','action','{"event_uid": "E123-03", "witnesses": ["C.wuxiaxian.WMAIN"], "action": "渤海爆发战争，中国自卫军攻击吴夏弦战舰。吴夏弦发国际广播承认战舰身份。", "motive": "公开身份，对抗军方", "causality": "战争全面爆发", "knowledge_change": "军长得知吴夏弦意图", "items": "战舰, 广播设备", "intervention_flag": "吴夏弦广播", "canon_src": "Chapter123"}',NULL);
INSERT INTO "events" VALUES(12401,0,'W-MAIN',0,124,'过去科技三角洲','action','{"event_uid": "E124-01", "witnesses": ["~米娅·海森堡", "~斯蒂芬·索恩", "~实验体131号"], "action": "米娅和索恩参观活体实验，目睹人造人(131号，即卡卡西)诞生。", "motive": "揭露人造人起源", "causality": "索恩和米娅大受震撼", "knowledge_change": "得知人造人制造过程", "items": "实验仪器", "intervention_flag": "人造人诞生", "canon_src": "Chapter124"}',NULL);
INSERT INTO "events" VALUES(12402,0,'W-MAIN',0,124,'工作室','action','{"event_uid": "E124-02", "witnesses": ["C.xiuzai.WMAIN", "C.weichu.WMAIN", "~米娅·海森堡"], "action": "修哉干涉北京军区干扰器信号，米娅向魏初传达活着的意义。", "motive": "支援战场，安抚同伴", "causality": "修哉辅助卡卡西", "knowledge_change": "魏初得到心灵慰藉", "items": "电脑", "intervention_flag": "修哉干涉信号", "canon_src": "Chapter124"}',NULL);
INSERT INTO "events" VALUES(12403,0,'W-MAIN',0,124,'海面战场','action','{"event_uid": "E124-03", "witnesses": ["C.kakashi.WMAIN", "C.zhangchen.WMAIN", "C.maki.WMAIN"], "action": "卡卡西利用量子流在深海呼吸，在海面布下巨型电网。张尘向真纪解释修哉与卡卡西的脑电波共振和命运联系。", "motive": "压制战场", "causality": "战场被电网笼罩", "knowledge_change": "众人得知修哉和卡卡西的深层联系", "items": "电网", "intervention_flag": "卡卡西布下电网", "canon_src": "Chapter124"}',NULL);
INSERT INTO "events" VALUES(12501,0,'W-MAIN',0,125,'过去看守所','action','{"event_uid": "E125-01", "witnesses": ["C.akito.WMAIN", "~折原正义"], "action": "秋人杀害父母后被正义审问，正义与秋人定下不伤害他人的约定，将秋人送往新环境。", "motive": "引导秋人向善", "causality": "秋人前往德国，命运改变", "knowledge_change": "无", "items": "约定协议", "intervention_flag": "正义与秋人约定", "canon_src": "Chapter125"}',NULL);
INSERT INTO "events" VALUES(12502,0,'W-MAIN',0,125,'世界政府看守房间','action','{"event_uid": "E125-02", "witnesses": ["C.akito.WMAIN", "~山崎聪"], "action": "秋人向山崎聪解释被注射的是微型芯片，世界政府如同电脑主板。", "motive": "解释世界政府技术", "causality": "山崎聪了解监控数据来源", "knowledge_change": "得知世界政府的微型芯片技术", "items": "微型芯片", "intervention_flag": "秋人解释技术", "canon_src": "Chapter125"}',NULL);
INSERT INTO "events" VALUES(12503,0,'W-MAIN',0,125,'秋人内心','action','{"event_uid": "E125-03", "witnesses": ["C.akito.WMAIN", "C.zhangchen.WMAIN"], "action": "秋人回忆其他世界中张尘送信的经历，回忆朋友们的羁绊，决定坚持活下去。", "motive": "选择活在这个世界", "causality": "秋人不再求死", "knowledge_change": "无", "items": "协议书(回忆)", "intervention_flag": "秋人的选择", "canon_src": "Chapter125"}',NULL);
INSERT INTO "events" VALUES(12601,0,'W-MAIN',0,126,'北京军区司令室','action','{"event_uid": "E126-01", "witnesses": ["~少校"], "action": "军长目睹战场局面，内心动摇，承认自己其实已经输了。", "motive": "信仰崩溃", "causality": "军长失去战斗意志", "knowledge_change": "无", "items": "无", "intervention_flag": "军长认输", "canon_src": "Chapter126"}',NULL);
INSERT INTO "events" VALUES(12602,0,'W-MAIN',0,126,'海面/深海','action','{"event_uid": "E126-02", "witnesses": ["C.kakashi.WMAIN", "C.xiuzai.WMAIN"], "action": "卡卡西力量透支，意识与修哉链接，感受到修哉的记忆与人类的复杂情感。", "motive": "意识共鸣", "causality": "卡卡西理解人类情感", "knowledge_change": "卡卡西获得修哉的记忆", "items": "无", "intervention_flag": "意识链接", "canon_src": "Chapter126"}',NULL);
INSERT INTO "events" VALUES(12603,0,'W-MAIN',0,126,'时空幻境','action','{"event_uid": "E126-03", "witnesses": ["C.kakashi.WMAIN", "~恐龙"], "action": "卡卡西遭到深海能量冲击，意识穿越至恐龙时代，与恐龙接触，恐龙表示相信他来自未来。", "motive": "跨越时空的接触", "causality": "体验生命的奇迹", "knowledge_change": "确认史前生命智慧(疑似)", "items": "岩画", "intervention_flag": "接触史前文明", "canon_src": "Chapter126"}',NULL);
INSERT INTO "events" VALUES(12604,0,'W-MAIN',0,126,'海面/甲板','action','{"event_uid": "E126-04", "witnesses": ["C.kakashi.WMAIN", "C.itachi.WMAIN", "C.liuxu.WMAIN"], "action": "卡卡西浑身发光浮出海面，鼬欲用十拳剑阻止但被神威转移。柳絮用声纳向卡卡西呼喊。", "motive": "阻止暴走/唤回意识", "causality": "卡卡西停止无差别攻击", "knowledge_change": "无", "items": "十拳剑, 声纳通讯器", "intervention_flag": "柳絮呼喊卡卡西", "canon_src": "Chapter126"}',NULL);
INSERT INTO "events" VALUES(12605,0,'W-MAIN',0,126,'海域上空','action','{"event_uid": "E126-05", "witnesses": ["~初音未来(RTW-DS-LT)"], "action": "伴随柳絮呼喊，初音未来立体影像出现，跳舞唱歌并向全世界广播世界政府及战争内幕。", "motive": "揭露真相", "causality": "各国决定停战", "knowledge_change": "全人类得知世界政府真相", "items": "广播影像", "intervention_flag": "初音未来广播", "canon_src": "Chapter126"}',NULL);
INSERT INTO "events" VALUES(12701,0,'W-MAIN',0,127,'世界政府走廊','action','{"event_uid": "E127-01", "witnesses": ["C.akito.WMAIN", "~山崎聪"], "action": "山崎聪趁网络漏洞救出秋人。秋人解释多重世界树状模型理论，决定向东走。", "motive": "逃亡与揭秘", "causality": "秋人脱离囚禁", "knowledge_change": "得知世界树理论", "items": "无", "intervention_flag": "秋人逃亡", "canon_src": "Chapter127"}',NULL);
INSERT INTO "events" VALUES(12801,0,'W-MAIN',0,128,'废弃机场/海滩','action','{"event_uid": "E128-01", "witnesses": ["C.zhangchen.WMAIN", "C.kakashi.WMAIN", "C.guojiazheng.WMAIN"], "action": "张尘告知晴明老索恩在美国自然死亡。张尘抱怨世界像缝合怪一样混乱。", "motive": "传递死讯", "causality": "晴明对索恩去世默哀", "knowledge_change": "晴明得知索恩死讯", "items": "无", "intervention_flag": "告知索恩死讯", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12802,0,'W-MAIN',0,128,'海滩机翼下','action','{"event_uid": "E128-02", "witnesses": ["C.zhangchen.WMAIN", "C.kakashi.WMAIN", "C.xiuzai.WMAIN"], "action": "张尘病情恶化吐血晕眩，随后强打精神与晴明、修哉拥抱并表达感激。", "motive": "身体极限与情感流露", "causality": "晴明感到恐慌，三人羁绊加深", "knowledge_change": "无", "items": "无", "intervention_flag": "张尘吐血", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12803,0,'W-MAIN',0,128,'海滩','action','{"event_uid": "E128-03", "witnesses": ["C.zhangchen.WMAIN", "C.xiuzai.WMAIN", "C.yamamoto_che.WMAIN"], "action": "山本告知各国领导邀请他们出席停战会议。张尘和修哉决定前往联合国面对质询。", "motive": "决定未来动向", "causality": "修哉和山本前往联合国", "knowledge_change": "无", "items": "无", "intervention_flag": "决定前往联合国", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12804,0,'W-MAIN',0,128,'过去记忆/集中营','action','{"event_uid": "E128-04", "witnesses": ["C.fein.WMAIN", "~恩师"], "action": "费恩回忆恩师带他去集中营教导他什么是群体罪恶与正直。", "motive": "铺垫反叛动机", "causality": "费恩坚守自己正直的信仰", "knowledge_change": "无", "items": "无", "intervention_flag": "费恩回忆恩师", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12805,0,'W-MAIN',0,128,'世界政府走廊','action','{"event_uid": "E128-05", "witnesses": ["C.fein.WMAIN", "C.yamato.WMAIN", "C.sai.WMAIN", "~萨缪尔·纳"], "action": "费恩等三人准备从内部反击，遇到萨缪尔。萨缪尔放行并告知秋人前往东方本体，并暗中掩护他们。", "motive": "内部反叛", "causality": "费恩三人得知秋人去向", "knowledge_change": "费恩得知秋人去向", "items": "无", "intervention_flag": "萨缪尔放行", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12806,0,'W-MAIN',0,128,'世界政府正门','action','{"event_uid": "E128-06", "witnesses": ["C.kakashi.WMAIN", "C.itachi.WMAIN", "C.zhangchen.WMAIN"], "action": "晴明利用卡卡西(RTW131)的身份通过人工智能认证，带领众人长驱直入。", "motive": "潜入总部", "causality": "众人顺利进入世界政府内部", "knowledge_change": "无", "items": "无", "intervention_flag": "晴明刷脸进入", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12807,0,'W-MAIN',0,128,'世界政府下水道','action','{"event_uid": "E128-07", "witnesses": ["~波风水门", "C.sasuke.WMAIN", "~清洁机器人"], "action": "佐助破坏清洁机器人以防上传数据，却引来大量无人机包围。", "motive": "潜入遭到阻碍", "causality": "水门与佐助陷入苦战", "knowledge_change": "无", "items": "机器人", "intervention_flag": "遭遇无人机包围", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12808,0,'W-MAIN',0,128,'世界政府内部','action','{"event_uid": "E128-08", "witnesses": ["C.zhangchen.WMAIN", "C.naruto.WMAIN", "~萨缪尔·纳"], "action": "鸣人击毁无人机引来大量增援。鸣人开启仙人模式保护张尘。萨缪尔出现放走张尘。", "motive": "保护张尘", "causality": "鸣人与张尘脱险并遇萨缪尔", "knowledge_change": "无", "items": "枪支", "intervention_flag": "鸣人开仙人模式", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12809,0,'W-MAIN',0,128,'世界政府大厅','action','{"event_uid": "E128-09", "witnesses": ["C.kakashi.WMAIN", "C.itachi.WMAIN", "~恐龙(化石)"], "action": "晴明与鼬来到大厅，看见巨大的恐龙化石，确认了曾经人类与恐龙的和平交流而非捕杀。", "motive": "见证历史遗迹", "causality": "晴明对人类历史有新理解", "knowledge_change": "得知恐龙化石真相", "items": "恐龙化石", "intervention_flag": "看到化石", "canon_src": "Chapter128"}',NULL);
INSERT INTO "events" VALUES(12901,0,'W-MAIN',0,129,'海边街道','action','{"event_uid": "E129-01", "witnesses": ["C.wuxiaxian.WMAIN", "C.maki.WMAIN", "C.liuyuntian.WMAIN"], "action": "吴夏弦给真纪披衣服并暗示心意，真纪看到刘云天后跑向他，吴夏弦彻底释怀。", "motive": "感情告结", "causality": "吴夏弦放弃追求真纪", "knowledge_change": "无", "items": "外套", "intervention_flag": "吴夏弦与真纪告别", "canon_src": "Chapter129"}',NULL);
INSERT INTO "events" VALUES(12902,0,'W-MAIN',0,129,'海边街道','action','{"event_uid": "E129-02", "witnesses": ["C.maki.WMAIN", "C.liuyuntian.WMAIN", "C.banbo.WMAIN", "C.yuxuan.WMAIN"], "action": "真纪与重伤的刘云天重逢相拥，刘云天向真纪求婚，两人重归于好。", "motive": "破镜重圆", "causality": "两人重新确立关系", "knowledge_change": "无", "items": "无", "intervention_flag": "刘云天求婚", "canon_src": "Chapter129"}',NULL);
