INSERT INTO "events" VALUES(12905,0,'W-MAIN',0,129,'联合国大厦走廊','action','{"event_uid": "E129-05", "witnesses": ["C.xiuzai.WMAIN", "C.yamamoto_che.WMAIN"], "action": "山本在开会前传达正义对修哉深沉的爱，修哉彻底解开心结，感到生命完整。", "motive": "解开父子心结", "causality": "修哉精神得到救赎", "knowledge_change": "确认父亲的爱", "items": "无", "intervention_flag": "山本传达正义之爱", "canon_src": "Chapter129"}',NULL);
