INSERT INTO "events" VALUES(12907,0,'W-MAIN',0,129,'世界政府议会室','action','{"event_uid": "E129-07", "witnesses": ["~议会元老"], "action": "议会元老们无视外界动荡，坚信建立无战争、残忍的理想国，不择手段。", "motive": "固守极端理念", "causality": "议会继续执行既定计划", "knowledge_change": "无", "items": "无", "intervention_flag": "议会决议", "canon_src": "Chapter129"}',NULL);
INSERT INTO "events" VALUES(12908,0,'W-MAIN',0,129,'世界政府监控室','action','{"event_uid": "E129-08", "witnesses": ["~波风水门", "C.sasuke.WMAIN"], "action": "水门利用修哉提供的光盘下载了人事部档案并传至云端。", "motive": "获取关键证据", "causality": "为修哉在联合国提供筹码", "knowledge_change": "无", "items": "光盘, 计算机", "intervention_flag": "水门下载档案", "canon_src": "Chapter129"}',NULL);
INSERT INTO "events" VALUES(12909,0,'W-MAIN',0,129,'世界政府议会室','action','{"event_uid": "E129-09", "witnesses": ["C.kakashi.WMAIN", "C.itachi.WMAIN", "~议会元老"], "action": "晴明和鼬攻入会议室，宣告议会的失败，议会成员被制裁。", "motive": "摧毁议会", "causality": "议会高层覆灭", "knowledge_change": "无", "items": "无", "intervention_flag": "制裁议会", "canon_src": "Chapter129"}',NULL);
INSERT INTO "events" VALUES(12910,0,'W-MAIN',0,129,'世界政府走廊','action','{"event_uid": "E129-10", "witnesses": ["C.kakashi.WMAIN", "C.itachi.WMAIN", "~武警"], "action": "晴明和鼬被大量无人机和武警包围，鼬选择留下断后，让晴明去和张尘汇合。", "motive": "掩护突围", "causality": "鼬独自迎战敌军", "knowledge_change": "无", "items": "枪支", "intervention_flag": "鼬留下断后", "canon_src": "Chapter129"}',NULL);
INSERT INTO "events" VALUES(13001,0,'W-MAIN',0,130,'斯德哥尔摩/联合国','action','{"event_uid": "E130-01", "witnesses": ["~国际警察", "~各国领导"], "action": "三战停火，国际警察攻入世界政府总部，发现人工智能已被修哉替换。", "motive": "攻占世界政府", "causality": "世界政府总部面临销毁", "knowledge_change": "无", "items": "无", "intervention_flag": "停战与攻占总部", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13002,0,'W-MAIN',0,130,'纽约直升机上','action','{"event_uid": "E130-02", "witnesses": ["C.xiuzai.WMAIN", "~米娅·海森堡"], "action": "修哉和米娅乘坐直升机前往斯德哥尔摩，修哉思考自己与晴明的脑波共鸣现象。", "motive": "探讨共鸣原理", "causality": "为修哉理解晴明经历做铺垫", "knowledge_change": "无", "items": "无", "intervention_flag": "探讨脑波共鸣", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13003,0,'W-MAIN',0,130,'世界政府走廊/电梯','action','{"event_uid": "E130-03", "witnesses": ["C.akito.WMAIN", "~山崎聪"], "action": "秋人和山崎聪被量产人造人追杀。山崎聪牺牲自己让秋人乘超载的电梯逃走。", "motive": "掩护逃生", "causality": "山崎聪牺牲，秋人逃亡LT", "knowledge_change": "无", "items": "电梯", "intervention_flag": "山崎聪牺牲", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13004,0,'W-MAIN',0,130,'世界政府执行部','action','{"event_uid": "E130-04", "witnesses": ["~萨缪尔·纳", "~国际警察"], "action": "萨缪尔被国际警察逮捕后，感觉生无可恋，服下慢性毒药自杀。", "motive": "信仰崩塌自杀", "causality": "萨缪尔死亡", "knowledge_change": "无", "items": "手铐, 毒药", "intervention_flag": "萨缪尔自杀", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13005,0,'W-MAIN',0,130,'世界政府某死角/走廊','action','{"event_uid": "E130-05", "witnesses": ["C.naruto.WMAIN", "C.zhangchen.WMAIN", "C.yamato.WMAIN", "C.fein.WMAIN", "C.sai.WMAIN"], "action": "鸣人为张尘殿后。大和为了引开死角外的人造人主动出击牺牲。", "motive": "掩护突围", "causality": "大和牺牲", "knowledge_change": "无", "items": "无", "intervention_flag": "大和牺牲", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13006,0,'W-MAIN',0,130,'世界政府清洁室','action','{"event_uid": "E130-06", "witnesses": ["C.zhangchen.WMAIN", "C.fein.WMAIN"], "action": "张尘被费恩救下，费恩为张尘挡下人造人的乱枪而牺牲，临死前宣告张尘是他的信仰。", "motive": "践行信仰", "causality": "费恩牺牲", "knowledge_change": "无", "items": "防弹衣(失效)", "intervention_flag": "费恩牺牲", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13007,0,'W-MAIN',0,130,'世界政府走廊','action','{"event_uid": "E130-07", "witnesses": ["C.zhangchen.WMAIN", "C.kakashi.WMAIN", "C.itachi.WMAIN"], "action": "张尘在极度悲痛下失去痛觉疯狂击杀人造人，最终被赶来的晴明和鼬救下。", "motive": "悲痛爆发", "causality": "张尘清剿沿途人造人", "knowledge_change": "无", "items": "手枪零件", "intervention_flag": "张尘暴走", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13008,0,'W-MAIN',0,130,'LT门前','action','{"event_uid": "E130-08", "witnesses": ["C.zhangchen.WMAIN", "C.kakashi.WMAIN", "C.itachi.WMAIN", "C.weichu.WMAIN"], "action": "张尘、晴明、鼬到达LT门口发现没带钥匙，魏初适时拿着钢笔出现。", "motive": "汇合开启LT", "causality": "凑齐开启LT的关键要素", "knowledge_change": "无", "items": "钢笔(LT钥匙)", "intervention_flag": "魏初送钥匙", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13009,0,'W-MAIN',0,130,'中东某战区','action','{"event_uid": "E130-09", "witnesses": ["C.xiuzai.WMAIN", "~耳聋小孩"], "action": "修哉驱车赶往斯德哥尔摩途中遭遇车祸，随后被当地耳聋且不懂语言的恐怖分子小孩误杀。", "motive": "意外死亡", "causality": "修哉意外死亡", "knowledge_change": "无", "items": "枪支", "intervention_flag": "修哉被杀", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13010,0,'W-MAIN',0,130,'LT门前/世界政府','action','{"event_uid": "E130-10", "witnesses": ["C.zhangchen.WMAIN", "C.kakashi.WMAIN", "C.weichu.WMAIN"], "action": "张尘用钢笔打开门，世界政府总部的异度空间开始塌陷消失，晴明冲入门内。魏初失去意识。", "motive": "毁灭世界政府空间", "causality": "世界政府彻底消失", "knowledge_change": "无", "items": "钢笔", "intervention_flag": "张尘开启LT大门", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13011,0,'W-MAIN',0,130,'世界政府废墟','action','{"event_uid": "E130-11", "witnesses": ["C.naruto.WMAIN", "~波风水门", "C.sasuke.WMAIN", "C.kakashi.WMAIN", "C.itachi.WMAIN", "C.zhangchen.WMAIN", "C.weichu.WMAIN"], "action": "幸存者向消失的世界政府敬礼。晴明、张尘、鼬和昏迷的魏初平安归来。", "motive": "劫后余生", "causality": "战斗彻底结束", "knowledge_change": "无", "items": "无", "intervention_flag": "众人归来", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13012,0,'W-MAIN',0,130,'停尸房内外','action','{"event_uid": "E130-12", "witnesses": ["C.kakashi.WMAIN", "C.maki.WMAIN", "C.zhangchen.WMAIN", "C.xiuzai.WMAIN", "C.wuxiaxian.WMAIN"], "action": "晴明得知修哉死讯。真纪在帐篷内悲痛欲绝。张尘听闻后癫狂大笑后哭喊崩溃。晴明向修哉遗体告别。", "motive": "获知死讯与告别", "causality": "众人陷入极度悲痛，晴明接受现实", "knowledge_change": "得知修哉死讯", "items": "无", "intervention_flag": "确认修哉死讯", "canon_src": "Chapter130"}',NULL);
INSERT INTO "events" VALUES(13101,0,'W-MAIN',0,131,'公寓','action','{"event_uid": "E131-01", "witnesses": ["C.kakashi.WMAIN", "C.itachi.WMAIN", "~张子琛"], "action": "战后，晴明回家，达也给阿琛梳头。两人一边喝啤酒一边感慨平淡但糟糕的生活。", "motive": "回归日常", "causality": "过上平淡生活", "knowledge_change": "无", "items": "啤酒, 梳子", "intervention_flag": "战后日常", "canon_src": "Chapter131"}',NULL);
INSERT INTO "events" VALUES(13102,0,'W-MAIN',0,131,'工作室','action','{"event_uid": "E131-02", "witnesses": ["C.itachi.WMAIN", "C.kakashi.WMAIN"], "action": "达也和晴明修理卡布机器人，晴明回忆修哉，并探讨人类存在的意义(只是存在本身)。", "motive": "回顾与释怀", "causality": "晴明领悟存在的意义", "knowledge_change": "无", "items": "卡布机器人", "intervention_flag": "修理卡布", "canon_src": "Chapter131"}',NULL);
INSERT INTO "events" VALUES(13103,0,'W-MAIN',0,131,'异世界记忆','action','{"event_uid": "E131-03", "witnesses": ["C.dust.W1", "C.ryuya.W1"], "action": "龙也死前，张尘对他说已经可以放弃了，让龙也传达给修哉不要再找他。", "motive": "跨时空诀别", "causality": "放弃在无尽轮回中的挣扎", "knowledge_change": "无", "items": "无", "intervention_flag": "张尘让龙也放弃", "canon_src": "Chapter131"}',NULL);
INSERT INTO "events" VALUES(13104,0,'W-MAIN',0,131,'疗养院','action','{"event_uid": "E131-04", "witnesses": ["C.zhangchen.WMAIN", "C.weichu.WMAIN", "C.banbo.WMAIN", "C.yuxuan.WMAIN"], "action": "两年后，张尘吃下大量安眠药，向魏初露出笑容，最终在魏初等人带来蛋糕时安静离世。", "motive": "结束生命", "causality": "张尘自杀离世", "knowledge_change": "无", "items": "安眠药, 蛋糕", "intervention_flag": "张尘离世", "canon_src": "Chapter131"}',NULL);
INSERT INTO "events" VALUES(13105,0,'W-MAIN',0,131,'公寓','action','{"event_uid": "E131-05", "witnesses": ["C.kakashi.WMAIN", "C.itachi.WMAIN"], "action": "晴明接到电话得知修哉遗体很久前被盗，怀疑是米娅所为，惊觉一切阴谋才刚刚开始。", "motive": "获知遗体被盗", "causality": "悬念迭起，和平可能被打破", "knowledge_change": "得知修哉遗体被盗", "items": "电话", "intervention_flag": "得知遗体被盗", "canon_src": "Chapter131"}',NULL);
INSERT INTO "events" VALUES(13106,0,'W-MAIN',0,131,'废弃实验室','action','{"event_uid": "E131-06", "witnesses": ["~米娅·海森堡", "C.xiuzai.WMAIN"], "action": "米娅尝试链接修哉的大脑，修哉大脑通过屏幕打出字幕询问“那个小孩最后说了什么”。", "motive": "科技复活", "causality": "修哉的大脑被唤醒", "knowledge_change": "确认修哉大脑存活", "items": "实验仪器, 电脑", "intervention_flag": "米娅唤醒修哉大脑", "canon_src": "Chapter131"}',NULL);
