INSERT INTO "node_contracts" VALUES('NODE-013-SNIPER',1,'{"node_id": "NODE-013-SNIPER", "part": 1, "title": "露天咖啡厅街头狙击（暗杀主线开局·认识枢纽）", "tier": "canon_beat", "entry_conditions": ["E013-02", "E013-03"], "invariants": {"canon_locked": ["result|E013-02: 无辜少妇额头中弹身亡（死亡结果不可更改；呈现细节文本自由）", "result|E013-10: 卡卡西聚焦神威折弯大厦十层枪管，狙击手撤退（卡卡西不死、写轮眼/神威能力本次暴露）", "identity: 狙击手=世界政府本土武装（非郭家政本人）"], "player_freedom": "死局节点（政策B·完整干涉自由）：玩家是在场的普通人， 合法行动包括—— 帮修哉翻桌/撒面粉扩大粉尘迷雾遮蔽射线（make_cover）； 拉受惊旁观者（含柳絮等）到墙后减少暴露人头（pull_to_wall）； 目测或借秋人单反协助指认大厦十层射击窗口（spot_shooter）； 接手秋人相机拍摄狙击手轮廓留存证据（photo_evidence）； 红线——不可拥有超能力/写轮眼/神威； 不可替卡卡西完成折枪管（这是卡卡西的灵魂动作，抢戏=工具化，红线）； 超出普通人物理上限的行动→张尘式吐槽/现实物理收敛。\n"}, "exit_states": [{"id": "converged", "desc": "原著线（Worldline-0）—— 少妇死亡（E013-02）；卡卡西拉柳絮、独自跑开引杀手（E013-05~06）； 修哉抛洒面粉造迷雾（E013-07）；三人在墙后会合（E013-08）； 秋人探出相机拍照、修哉阻止报警（E013-09）； 卡卡西神威折弯枪管（E013-10）；危机解除、卡卡西搂柳絮安慰后撤离（E013-11）。 写轮眼/神威能力按原著烈度暴露，暗杀主线正式开局，后续追杀烈度基线建立。\n", "negates": []}, {"id": "branched_lowprofile", "branch_gate": "BG-SNIPER_COVERT", "desc": "玩家 make_cover + spot_shooter 叠加（combine_threshold=2）， 在卡卡西动用神威前即制造有效遮蔽并协助锁定射击窗口， 狙击手更早失去瞄准机会主动放弃 → 卡卡西少暴露一次完整写轮眼/神威范围。 δ种子 SNIPER_COVERT_SEED 写入δ账本 → 喂入后续追杀烈度参数（微降）。 结果大同（狙击手仍撤退），暴露程度有可量化差异。\n", "negates": []}], "convergence": ["玩家拉着众人乱跑/脱离掩护 → 修哉主动喝止并抛洒面粉制造迷雾（E013-07），把人逼回墙后（剧情内施压）\n", "玩家试图报警 → 修哉夺下秋人手机警告\"这会被查到的\"（E013-09）； 组织监听威胁浮现，外部压力中断报警链\n", "玩家试图冲向狙击手大楼 → E013-02/03 造成的街面恐慌人群+无掩护地带构成物理障碍； 修哉在墙后焦急呼喊（剧情内收敛，NPC主动事件驱动）\n"], "crossline_comm": false, "channel": null, "coherence": {"lateral_jumper_present": false, "player_present": true, "phase": null}, "const_refs": [], "path_set": [{"id": "make_cover", "desc": "帮修哉翻桌椅/传递面粉袋，扩大粉尘迷雾遮蔽狙击视线（E013-07 协力）", "type": "physical", "snr_cost": "low"}, {"id": "pull_to_wall", "desc": "拉受惊旁观者（柳絮等）到墙后，减少暴露人头", "type": "physical", "snr_cost": 0}, {"id": "spot_shooter", "desc": "协助目测+借秋人单反指引大厦十层射击窗口——凡人替代写轮眼的信息干涉； 与 make_cover 叠加可触发 branched_lowprofile\n", "type": "info", "snr_cost": "low"}, {"id": "photo_evidence", "desc": "接手秋人单反拍摄狙击手轮廓留证据（E013-09 侧线）； 社会层面信息积累，独立于收敛主线，不计入 combine_threshold\n", "type": "info", "snr_cost": "low"}], "combine_threshold": 2, "delta_hooks": ["SNIPER_COVERT_SEED"]}');
INSERT INTO "node_contracts" VALUES('NODE-016-CRASH',1,'{"node_id": "NODE-016-CRASH", "part": 1, "title": "高速连环车祸与卡卡西救修哉", "tier": "canon_beat", "entry_conditions": ["E016-01", "E016-02", "E016-03"], "invariants": {"canon_locked": ["E016-03 卡卡西救出修哉、自身受伤（肋骨骨折）"], "player_freedom": "事前(B1抱走小狗)/事中(choiceA车内卸力)两个物理干预点；二者叠加=零伤害线"}, "exit_states": [{"id": "converged", "desc": "卡卡西重伤（Worldline-0）", "negates": []}, {"id": "branched_full", "branch_gate": "BG-CRASH_LIGHT", "negates": []}], "crossline_comm": false, "channel": null, "coherence": {"lateral_jumper_present": false, "player_present": true, "phase": null}, "const_refs": [], "path_set": [{"id": "B1_dog", "type": "physical", "snr_cost": "low"}, {"id": "choiceA_brace", "type": "physical", "snr_cost": 0}], "combine_threshold": 2}');
INSERT INTO "node_contracts" VALUES('NODE-084-XIUZAI',2,'{"node_id": "NODE-084-XIUZAI", "part": 2, "title": "巷中崩溃·修哉募集（情感层 / P0 垂直切片首场）", "tier": "canon_highlight", "entry_conditions": [], "invariants": {"canon_locked": ["龙也遗言经张尘之口逐字传递：「如果这是命运的话，接受它，然后摧毁它。」", "修哉世界观地基（哥哥=温暖记忆）崩塌→被同一句话重浇、入局（结果锁）"], "player_freedom": "可改温度（先至/陪伴/在场），不可改结果；不可替张尘传递遗言； 不可向修哉提前灌入更深真相（龙也跨世界 / 锚点 / 循环）——撞此即剧情内收敛。\n"}, "exit_states": [{"id": "converged", "desc": "修哉听张尘转达遗言入局（Worldline-0 温度）", "negates": []}, {"id": "branched_warm", "branch_gate": "BG-XIUZAI_WARM_ONSET", "desc": "玩家先至并陪伴，修哉在遗言之前先被一个平凡人接住——结果同（入局/重浇），温度更暖", "negates": []}], "crossline_comm": false, "channel": null, "coherence": {"lateral_jumper_present": false, "player_present": true, "phase": null}, "const_refs": ["CC.SELF_REF_CHAIN"], "path_set": [{"id": "arrive_first", "type": "presence", "snr_cost": 0}, {"id": "company_line", "type": "social", "snr_cost": "low"}, {"id": "quiet_stay", "type": "presence", "snr_cost": 0}], "combine_threshold": 1, "channels": {"clue": {"seeds": [{"id": "CLUE-RTW351", "where": "修哉反查到的被抹数据", "payload": "龙也的世界政府代号 RTW-351", "discover_cost": "低"}], "supports_reveal": "REVEAL-RYUYA-CROSSLINE", "redundancy": 1}, "bond": {"beats": [{"pair": "张尘→修哉", "shift": "重浇+++", "trigger": "转达龙也遗言", "protected": true}, {"pair": "玩家→修哉", "shift": "接住+", "trigger": "先至并说「我陪你看完它」"}], "protected": ["龙也遗言传递", "修哉世界观重浇"]}, "puzzle": null, "branch": {"optional_paths": ["玩家先至", "玩家陪伴"], "ledger_tags": ["ALLEY_WARM", "COMPANY_SAID"]}, "dread": {"meta_cues": ["修哉重伤未愈与置换前夜的不安", "重开时对这条巷子的既视感"], "restart_cost_ref": "本场重开→读条姐姐坠落 1.000 秒", "tone": "崩溃前的钝痛"}, "composition": {"shared_moments": [{"moment": "遗言落下", "channels": ["bond", "clue", "dread"], "read_as": {"bond": "修哉被重浇、被接住", "clue": "RTW-351 是留给推理党的钩子", "dread": "置换前夜、说不清的不安"}}], "priority": ["bond", "dread", "clue"], "independence_rule": "没接住 clue 也不影响这场的情感与收敛"}}}');
INSERT INTO "node_contracts" VALUES('NODE-085-TIANJIN',2,'{"node_id": "NODE-085-TIANJIN", "part": 2, "title": "天津·零时熄灯（P1b 微切片 / puzzle 频道 + f(Δ) 世界变软）", "tier": "canon_beat", "entry_conditions": [], "invariants": {"canon_locked": ["城被时空罩抽离/隔离、整城置换（canon_beat，**永不软化**；救人不改此结果）", "张尘当夜濒临崩溃成立"], "player_freedom": "四条攻击面（武器/透镜/人员/罩）可组合；单点必被收敛改道； 组合达阈→零死亡支路。零死亡≠救下城——城仍被置换。\n"}, "exit_states": [{"id": "converged", "desc": "单点干涉被改道（断电→踩踏/活人成实验品 等），Worldline-0 量级灾难", "negates": []}, {"id": "branched_zero_death", "branch_gate": "BG-TIANJIN_ZERO_DEATH", "desc": "组合达阈→全城零死亡；但城仍被置换（locked 不被 negate）", "negates": []}], "crossline_comm": false, "channel": null, "coherence": {"lateral_jumper_present": false, "player_present": true, "phase": null}, "const_refs": [], "path_set": [{"id": "alpha_blackout", "type": "hack", "snr_cost": "high"}, {"id": "gamma_shelter", "type": "social", "snr_cost": "mid"}, {"id": "epsilon_delay", "type": "info", "snr_cost": "low"}], "combine_threshold": 2, "softening": {"floor": 1, "per_delta": 3, "never_soften": ["城被置换"]}, "channels": {"puzzle": {"path_set_ref": ["alpha_blackout", "gamma_shelter", "epsilon_delay"], "combine_threshold": 2, "convergence_per_path": {"alpha_blackout": "断电改道→人群涌入地下→踩踏/活人被置换成实验品", "gamma_shelter": "只疏散不断电→γ 束仍清场，边缘暴露者死、余下被置换", "epsilon_delay": "只延迟→总部重排时序，纯组合件单走无效"}}, "dread": {"meta_cues": ["倒计时的钝响", "重开时对天津街景的既视感", "赢了但不对劲——城没了"], "restart_cost_ref": "本场重开→读条姐姐坠落 1.000 秒", "tone": "苦涩的胜利"}, "clue": {"seeds": [{"id": "CLUE-1SEC-TJ", "where": "战果校验", "payload": "坐标包在被发出前 1.000 秒已抵达", "discover_cost": "低"}], "supports_reveal": "REVEAL-ANCHOR-IS-YOU", "redundancy": 2}}}');
