INSERT INTO "propositions" VALUES('P.RTW_EXISTS','世界政府/RTW 组织确实存在并暗中控制秩序',2,'Ch.7/41');
INSERT INTO "propositions" VALUES('P.GF_DEATH_TRUTH','女友苏颖四年前在十六中正门坠楼死亡，真相为折原龙也亲手推下',3,'Ch.41/60');
INSERT INTO "propositions" VALUES('P.RYUYA_DEATH_TRUTH','折原龙也因与世界政府利益对抗而选择假死，并设计弑父（折原正义）以完成最终交换',2,'Ch.60');
INSERT INTO "propositions" VALUES('P.SEIMEI_MACHINE','晴明君（黑发坂本卡卡西）并非原生人类，而是人造机体，内部搭载异世界折原修哉的大脑',3,'Ch.98/113');
INSERT INTO "propositions" VALUES('P.DUST_CREATOR','世界政府/RTW 实际上是物理跃迁者尘叔（Dust）在更早世界线中创建的',3,'Ch.110');
INSERT INTO "propositions" VALUES('P.FIRST_WORLD_PROMISE','第一世界中尘叔与折原修哉在斯德哥尔摩大火中离别，并约定“一定会带你回来”',3,'Ch.111');
INSERT INTO "propositions" VALUES('P.RTW131_IDENTITY','银发卡卡西并非普通人类，而是初代人造人实验体 RTW131',3,'Ch.78/92');
INSERT INTO "propositions" VALUES('P.WEICHU_WIDOW','魏初是已故世界政府高层折原龙也的遗孀，并暗中卷入因果中枢',2,'Ch.19/96');
INSERT INTO "propositions" VALUES('P.BLACKOUT_SECRET','Ch.85全城断电是本体张尘瞒着尘叔的擅自慈悲，尘叔的城市置换计划因此被破坏；本体下令时心虚',3,'B5决议#2');
INSERT INTO "propositions" VALUES('P.DS_PUPPET','DS本质为尘叔所建；本体张尘为台前执行者，按尘叔安排行事、承压巨大且低估自己真实的号召力',3,'B5决议#2');
INSERT INTO "propositions" VALUES('P.RYUYA_CORESIDENT','主世界龙也一身两意识共驻（本体+W1意识），对外呈现为人格分裂',3,'B5决议·总裁定');
INSERT INTO "propositions" VALUES('P.PLAYER_RYUYA_HISTORY','龙也（W1意识前台）在影子岁月中受钥匙指引找到玩家，以日常接触切入，两年间建立君子之交；临终交付挂坠（钥匙）',2,'B5决议·附加·2026-07-28修订');
